#!/usr/bin/env python3
"""Create a hardcopy-ready PDF report from the measured experiment outputs."""
from pathlib import Path
import pandas as pd
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

ROOT = Path(__file__).resolve().parents[1]
RESULTS = ROOT / "results"
OUT = ROOT / "report" / "WL_Kernel_Assignment_Report.pdf"


def fmt(x):
    return f"{x:.3f}"


def main():
    csv_path = RESULTS / "metrics.csv"
    summary_path = RESULTS / "summary.json"
    if not csv_path.exists() or not summary_path.exists():
        raise SystemExit("Run `python src/run_experiment.py` first; results/metrics.csv is missing.")
    import json
    summary = json.loads(summary_path.read_text())
    df = pd.read_csv(csv_path)
    baseline = df[df.method == "WL subtree (h=3)"].iloc[0]
    modified = df[df.method == "Edge-aware WL (h=3)"].iloc[0]
    best = df.sort_values(["macro_f1", "accuracy"], ascending=False).iloc[0]

    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="CoverTitle", parent=styles["Title"], alignment=TA_CENTER, fontSize=18, leading=22, spaceAfter=14))
    styles.add(ParagraphStyle(name="Small", parent=styles["BodyText"], fontSize=8, leading=10))
    story = []
    story += [Spacer(1, 20*mm), Paragraph("An Empirical Study of an Edge-Aware<br/>Weisfeiler–Lehman Subtree Kernel", styles["CoverTitle"]),
              Paragraph("Assignment 3 — Graph Machine Learning", styles["Heading2"]), Spacer(1, 5*mm),
              Paragraph("Student: Harish", styles["BodyText"]), Paragraph("Dataset: MUTAG molecular graph classification benchmark", styles["BodyText"]),
              Paragraph("Report generated from measured cross-validation results", styles["BodyText"]), Spacer(1, 20*mm),
              Paragraph("Abstract", styles["Heading1"]),
              Paragraph("This project implements the Weisfeiler–Lehman (WL) subtree kernel from scratch and evaluates a bond-aware extension on the MUTAG molecular graph benchmark. The baseline refines node labels using neighbouring node labels; the modified method also incorporates chemical bond labels. A precomputed-kernel support vector machine is evaluated using repeated stratified 10-fold cross-validation. The reported results are generated by the included code, not manually estimated.", styles["BodyText"]),
              PageBreak()]
    story += [Paragraph("1. Introduction", styles["Heading1"]),
              Paragraph("Graph kernels compare graphs through structural patterns and let standard kernel classifiers operate on graph-structured data. Shervashidze et al. (2011) introduced an efficient WL graph-kernel framework based on iterative node-label refinement. This project tests whether including bond labels in the refinement step affects molecular classification.", styles["BodyText"]),
              Paragraph("2. Dataset", styles["Heading1"]),
              Paragraph(f"MUTAG contains {summary['n_graphs']} molecular graphs, {summary['n_nodes']} nodes and {summary['n_edges']} edges in total. Nodes represent atoms and edges represent chemical bonds. The target is binary mutagenicity classification. The dataset is a standard benchmark, but its small size means the measured results have uncertainty.", styles["BodyText"]),
              Paragraph("3. Methods", styles["Heading1"]),
              Paragraph("Standard WL subtree kernel: initialise node labels from atom types, iteratively form signatures from each node's current label and the sorted multiset of neighbouring labels, compress identical signatures to shared identifiers, and count labels at each height. The graph kernel is the dot product of L2-normalised label-count feature vectors.", styles["BodyText"]),
              Paragraph("Edge-aware modification: each refinement signature includes the current node label and a sorted multiset of (bond label, neighbour label) pairs. A further ablation applies depth decay 0.7^h to reduce the weight of higher-order patterns. The implementation is from scratch and does not call a prebuilt WL-kernel library.", styles["BodyText"]),
              Paragraph("4. Experimental setup", styles["Heading1"]),
              Paragraph("All variants use an SVM with a precomputed kernel and C=1.0. Evaluation uses repeated stratified 10-fold cross-validation, 10 repeats, random seed 42. Metrics are averaged across test folds and include accuracy, balanced accuracy, macro-F1, ROC-AUC and runtime. The same protocol is used for every variant.", styles["BodyText"]),
              Paragraph("5. Results", styles["Heading1"])]
    headers = ["Method", "Accuracy", "Balanced acc.", "Macro-F1", "ROC-AUC", "Runtime (s)"]
    rows = [headers]
    for _, r in df.iterrows():
        rows.append([str(r.method), f"{r.accuracy:.3f} ± {r.accuracy_std:.3f}", f"{r.balanced_accuracy:.3f}", f"{r.macro_f1:.3f} ± {r.macro_f1_std:.3f}", f"{r.roc_auc:.3f} ± {r.roc_auc_std:.3f}", f"{r.runtime_seconds:.2f}"])
    table = Table(rows, repeatRows=1, colWidths=[48*mm, 25*mm, 24*mm, 25*mm, 23*mm, 20*mm])
    table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#203864")), ("TEXTCOLOR", (0,0), (-1,0), colors.white),
        ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"), ("FONTSIZE", (0,0), (-1,-1), 7),
        ("GRID", (0,0), (-1,-1), 0.35, colors.grey), ("VALIGN", (0,0), (-1,-1), "MIDDLE"),
        ("ROWBACKGROUNDS", (0,1), (-1,-1), [colors.white, colors.HexColor("#F1F4F8")]),
        ("LEFTPADDING", (0,0), (-1,-1), 4), ("RIGHTPADDING", (0,0), (-1,-1), 4),
        ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5),
    ]))
    story += [table, Spacer(1, 4*mm),
              Paragraph(f"At height 3, standard WL accuracy is {baseline.accuracy:.3f} ± {baseline.accuracy_std:.3f}, macro-F1 is {baseline.macro_f1:.3f} ± {baseline.macro_f1_std:.3f}, and ROC-AUC is {baseline.roc_auc:.3f} ± {baseline.roc_auc_std:.3f}.", styles["BodyText"]),
              Paragraph(f"Edge-aware WL at height 3 obtains accuracy {modified.accuracy:.3f} ± {modified.accuracy_std:.3f}, macro-F1 {modified.macro_f1:.3f} ± {modified.macro_f1_std:.3f}, and ROC-AUC {modified.roc_auc:.3f} ± {modified.roc_auc_std:.3f}.", styles["BodyText"]),
              Paragraph(f"The difference in mean accuracy is {modified.accuracy-baseline.accuracy:+.3f}; the difference in mean macro-F1 is {modified.macro_f1-baseline.macro_f1:+.3f}. The best tested method by macro-F1 is {best.method} (macro-F1 {best.macro_f1:.3f}).", styles["BodyText"]),
              Paragraph("6. Discussion", styles["Heading1"]),
              Paragraph("The edge-aware signature is more expressive because it distinguishes bond types when aggregating neighbourhood information. Greater expressiveness does not guarantee improved predictive performance: additional distinctions can help or add noise, especially with limited data. Interpret the observed changes as evidence on MUTAG rather than a universal result. Cross-validation reduces dependence on a single split but does not remove uncertainty.", styles["BodyText"]),
              Paragraph("7. Conclusion", styles["Heading1"]),
              Paragraph(f"The project implemented standard WL subtree features and an edge-aware variant, then compared them under a consistent SVM evaluation protocol. In this run, the edge-aware variant changed mean accuracy by {modified.accuracy-baseline.accuracy:+.3f} and macro-F1 by {modified.macro_f1-baseline.macro_f1:+.3f}. The best configuration was {best.method}. These findings are limited to the MUTAG benchmark and the tested settings.", styles["BodyText"]),
              Paragraph("References", styles["Heading1"]),
              Paragraph("[1] Shervashidze, N., Schweitzer, P., van Leeuwen, E. J., Mehlhorn, K., & Borgwardt, K. M. (2011). Weisfeiler-Lehman Graph Kernels. Journal of Machine Learning Research, 12, 2539–2561.", styles["Small"]),
              Paragraph("[2] Morris, C., Kriege, N. M., Kersting, K., & Mutzel, P. (2016). Faster Kernels for Graphs with Continuous Attributes via Hashing. IEEE ICDM 2016, 1095–1100.", styles["Small"]),
              Paragraph("[3] Togninalli, M., Ghisu, E., Llinares-López, F., Rieck, B., & Borgwardt, K. (2019). Wasserstein Weisfeiler-Lehman Graph Kernels. NeurIPS 2019.", styles["Small"]),
              Paragraph("[4] Debnath, A. K., et al. (1991). Structure-activity relationship of mutagenic aromatic and heteroaromatic nitro compounds. Journal of Medicinal Chemistry, 34(2), 786–797.", styles["Small"])]
    OUT.parent.mkdir(parents=True, exist_ok=True)
    doc = SimpleDocTemplate(str(OUT), pagesize=A4, rightMargin=16*mm, leftMargin=16*mm, topMargin=15*mm, bottomMargin=15*mm, title="Edge-Aware Weisfeiler-Lehman Kernel Assignment")
    doc.build(story)
    print(f"Created {OUT}")

if __name__ == "__main__":
    main()
